#!/bin/bash
# GENERATED by tools/codex-sync — do not edit.
# Source: disallowedTools in .claude/agents/*.md
#
# Codex PreToolUse hook. Claude Code expresses "this role may write files but
# may not run shell commands" with `disallowedTools: Bash`. Codex has no
# per-role tool allowlist, and sandbox_mode cannot express it either --
# read-only would also block apply_patch, which these roles need.
#
# So it is enforced here, keyed on the agent_type that Codex includes in hook
# stdin. Exit 2 blocks the call.

INPUT=$(cat)

if command -v jq >/dev/null 2>&1; then
    AGENT=$(echo "$INPUT" | jq -r '.agent_type // empty')
else
    AGENT=$(echo "$INPUT" | grep -oE '"agent_type"[[:space:]]*:[[:space:]]*"[^"]*"' | sed 's/.*:[[:space:]]*"//;s/"$//')
fi

# No agent_type means the main thread, which is not restricted.
[ -z "$AGENT" ] && exit 0

case "$AGENT" in
    art-director | audio-director | community-manager | creative-director | economy-designer | game-designer | level-designer | live-ops-designer | narrative-director | sound-designer | systems-designer | ue-blueprint-specialist | ux-designer | world-builder | writer)
        echo "BLOCKED: the '$AGENT' role may not run shell commands (disallowedTools: Bash)." >&2
        echo "Read and edit files directly instead." >&2
        exit 2
        ;;
esac

exit 0
